INSERT INTO `proyectos` (`id`, `nombre`, `descripcion`, `fecha_inicio`, `fecha_fin`, `porcentaje`, `area_id`, `estado`, `created_at`, `updated_at`, `user_id`) VALUES
(1, 'Sistemas de Facturación', 'En actualizaciones', '2025-07-30', NULL, 41.00, 9, 1, '2025-09-24 16:05:29', '2025-09-24 16:05:29', NULL),
(2, 'Citas Medicas', 'Sistema de Citas Medicas', '2025-07-15', NULL, 25.00, 13, 1, '2025-09-29 14:45:06', '2025-10-01 18:56:57', NULL),
(3, 'Planillas', 'Proyecto de Planillas', '2025-09-10', NULL, 35.00, 21, 1, '2025-09-29 14:51:04', '2025-09-29 14:51:04', NULL),
(4, 'Aplicación para restaurantes', 'Gestión de inventarios, personal, caja.', '2025-07-26', NULL, 90.00, 10, 1, '2025-09-29 16:43:35', '2025-09-29 16:43:35', 142),
(5, 'Sistema de reservas y gestión de vehículos', '- Realización del query y entidad-relación para MySQL \r\n- Terminar detalles del sistema\r\n- Afinar detalles y describir funcionalidad del sistema', '2025-08-15', '2025-09-15', 100.00, 5, 1, '2025-09-29 17:07:59', '2025-10-28 04:36:54', 142),
(6, 'Gestión de proyectos', '- Analisis del sistema y documentación.\r\n- Testeo del sistema beta \r\n- Desarrollo del entidad-relación \r\n- Realizando figma de las vistas a modificar', '2025-09-16', '2025-10-24', 100.00, 5, 1, '2025-09-29 17:10:13', '2025-10-28 04:38:12', 142),
(7, 'Chat en tiempo real', 'Crear un sistema de chat en tiempo real con canales públicos y privados, mensajería directa, y gestión de usuarios.', '2025-09-24', NULL, 95.00, 24, 1, '2025-10-27 15:09:46', '2025-10-27 15:09:46', 142),
(8, 'El sistema de tickets', 'Una app donde una empresa pide servicio de soporte', '2025-03-15', NULL, 70.00, 22, 1, '2025-10-27 19:51:27', '2025-10-27 19:51:27', 142),
(9, 'Chat service', 'Es un chat que nos permite ingresar usuarios, agregar nuevos usuarios a través de un login y que van directamente a la base de datos implementada en el mismo archivo, así sucesivamente los mensajes y la hora enviada del mensaje además del usuario que mando el mensaje se quedan guardados en la base de datos, a través del terminal se ve el código del usuario y el nombre cuando un usuario ingresa\r\nAdemás se ve los demás mensajes con otros usuarios sin necesidad de ir a la anterior página para poder visualizarlo', '2025-10-06', NULL, 70.00, 26, 1, '2025-10-27 19:55:37', '2025-10-27 19:55:37', 142),
(10, 'CRM con integración a la API whatsapp business para la gestion de clientes', 'Un whatsapp en el cual se quiera para gestionar la cuenta de la empresa', '2025-08-25', NULL, 70.00, 20, 1, '2025-10-27 19:57:39', '2025-10-27 19:57:39', 142),
(11, 'Proyecto de filtrado de documentos con IA', 'Mejorar la precision del filtrado de documentos', '2025-08-15', NULL, 80.00, 15, 1, '2025-10-27 20:03:12', '2025-10-27 20:03:12', 142),
(12, 'Chatbot asistente virtual', 'Es un asistente de voz inteligente desarrollado en Python, con una interfaz futurista echa en CustomTkinter.\r\nSu funcionamiento tiene reconocimiento de voz, síntesis de voz, animaciones visuales y conexión a un modelo de lenguaje avanzado (Gemini de Google) para mantener conversaciones naturales y ejecutar comandos hablados.', '2025-07-05', NULL, 80.00, 16, 1, '2025-10-27 20:03:42', '2025-10-27 20:03:42', 142),
(13, 'HelpDesk (mejora)', '-Documentación\r\n-Requerimientos\r\n-Diagrama Entidad-Relación y MySQL\r\n-Informe de funcionalidades y componentes\r\n-Análisis del sistema\r\n-Desarrollo del figma (desde 0)\r\n-Integración de mejoras de diseño y funcionalidades', '2025-10-26', '2025-12-15', 10.00, 5, 0, '2025-10-28 04:45:05', '2025-11-17 21:01:27', 25),
(14, 'App sistema de taxis', 'El chofer utiliza una aplicación móvil para visualizar los viajes que tiene asignados, aceptar nuevos servicios y gestionar su progreso. La app permite al conductor ver detalles del viaje, como origen, destino, horario y estado, facilitando la ejecución eficiente de cada servicio.', '2025-09-11', NULL, 95.00, 7, 1, '2025-10-29 15:33:53', '2025-12-15 04:34:47', 142),
(15, 'Actualización del sistema de asistencias Zeit', 'El sistema de asistencias Zeit se está fortaleciendo con nuevas funcionalidades de gestión de tareas, permitiendo un control más estructurado y eficiente de cada asistencia. Se incorporan estados definidos, asignación de responsables y seguimiento activo. Además, se mejora la interactividad del sistema mediante formularios dinámicos, notificaciones contextuales y una interfaz más intuitiva, facilitando la participación de los usuarios en tiempo real.', '2025-09-15', NULL, 40.00, 25, 1, '2025-10-29 15:35:31', '2025-10-29 15:35:31', 142);
